insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_46_v1'
from (values
('127.257.d.1.A',3,'A manager uses a cost report to decide whether a second shift is worth running. This is mathematics applied to:','["A real business decision", "A pure puzzle", "A spelling exercise", "A historical event"]'::jsonb,0,'Business math supports decisions.','original'),
('127.257.d.1.A',4,'An accountant estimates how a 5% price cut changes yearly profit using a spreadsheet. This applies mathematics to:','["A drawing task", "A problem arising in business and society", "A purely theoretical proof", "A random guess"]'::jsonb,1,'Math models real situations.','original'),
('127.257.d.1.B',3,'In a problem-solving model, ''evaluate the problem-solving process and the reasonableness of the solution'' comes:','["Before reading the problem", "Instead of planning", "After carrying out the plan", "Never"]'::jsonb,2,'Evaluation closes the process.','original'),
('127.257.d.1.B',4,'An analyst''s computed profit margin is 450%. A good problem solver would:','["Ask for a bonus", "Delete the data", "Report it unchanged", "Recheck the work because the result is unreasonable"]'::jsonb,3,'A margin over 100% signals an error.','original'),
('127.257.d.1.C',3,'For adding hundreds of invoices and graphing the totals, the best tool is:','["A spreadsheet", "A compass", "A stopwatch", "A ruler"]'::jsonb,0,'Spreadsheets handle large data.','original'),
('127.257.d.1.C',4,'When estimating an answer quickly before using a calculator, an accountant is using:','["A random choice", "Mental math and estimation", "A map", "A sundial"]'::jsonb,1,'Estimating checks results.','original'),
('127.257.d.1.D',3,'Explaining a variance to a manager in plain words and numbers is:','["Avoiding analysis", "Skipping steps", "Communicating mathematical reasoning", "Hiding data"]'::jsonb,2,'Communication includes explanation.','original'),
('127.257.d.1.D',4,'A strong written justification for a budget change includes the figures and:','["Unrelated facts", "A hunch", "No units", "A clear explanation of how they support the decision"]'::jsonb,3,'Reasoning ties numbers to conclusions.','original'),
('127.257.d.1.E',3,'A bar chart of quarterly sales is a:','["Representation that organizes and communicates data", "Hidden record", "Contract", "Random drawing"]'::jsonb,0,'Charts display data.','original'),
('127.257.d.1.E',4,'To show how each dollar of revenue is divided among costs and profit, an accountant might use:','["A recipe", "A common-size income statement or pie chart", "A seating chart", "A weather map"]'::jsonb,1,'Common-size statements show proportions.','original'),
('127.257.d.1.F',3,'Seeing that higher sales volume lowers fixed cost per unit is analyzing:','["A coincidence", "A rumor", "A mathematical relationship", "A color scheme"]'::jsonb,2,'Fixed costs spread over more units.','original'),
('127.257.d.1.F',4,'Connecting a break-even formula to the point where two lines cross on a graph is:','["Ignoring models", "Guessing", "Memorizing", "Linking mathematical relationships to representations"]'::jsonb,3,'Algebra and graphs agree.','original'),
('127.257.d.1.G',3,'Using calculations and a chart to defend a pricing proposal to the owner is:','["Justifying a mathematical argument", "Offering an opinion only", "Skipping proof", "Delaying work"]'::jsonb,0,'Justification uses evidence.','original'),
('127.257.d.1.G',4,'Which best supports the claim ''Product A is more profitable than Product B''?','["A statement that A is newer", "A comparison of contribution margins with calculations shown", "A popularity poll", "A coin flip"]'::jsonb,1,'Evidence beats assertion.','original'),
('127.257.d.2.A',3,'Articles of incorporation must be reviewed to learn how many shares a corporation is:','["Sold last year", "Held by the CEO", "Authorized to issue", "Owed to the bank"]'::jsonb,2,'Authorized shares are stated in the articles.','original'),
('127.257.d.2.A',4,'If the articles authorize 100,000 shares and 60,000 have been issued, the shares still available are:','["160,000", "100,000", "60,000", "40,000"]'::jsonb,3,'100,000 - 60,000 = 40,000.','original'),
('127.257.d.2.B',3,'When a corporation sells 2,000 shares of $5 par stock for $12 per share, the amount credited to common stock is:','["$10,000", "$12,000", "$14,000", "$24,000"]'::jsonb,0,'2,000 x 5 = 10,000 at par.','original'),
('127.257.d.2.B',4,'In that same sale the excess over par credited to paid-in capital is:','["$24,000", "$14,000", "$7,000", "$10,000"]'::jsonb,1,'2,000 x (12 - 5) = 14,000.','original'),
('127.257.d.2.C',3,'Each share of convertible preferred stock converts into 3 shares of common stock. When 1,000 preferred shares convert, the corporation issues:','["333 common shares", "1,000 common shares", "3,000 common shares", "30,000 common shares"]'::jsonb,2,'1,000 x 3 = 3,000.','original'),
('127.257.d.2.C',4,'Convertible preferred with a $100 par value converts at $25 per common share. Common shares per preferred share:','["25", "2.5", "0.25", "4"]'::jsonb,3,'100 / 25 = 4.','original'),
('127.257.d.2.D',3,'A corporation has 5,000 shares of 6%, $100 par preferred stock. Annual preferred dividends are:','["$30,000", "$300,000", "$6,000", "$3,000"]'::jsonb,0,'5,000 x 100 x 0.06 = 30,000.','original'),
('127.257.d.2.D',4,'The corporation then has $10,000 left for 50,000 common shares. The common dividend per share is:','["$20", "$0.20", "$0.02", "$2.00"]'::jsonb,1,'10,000 / 50,000 = 0.20.','original'),
('127.257.d.2.E',3,'Requiring a manager''s approval before a large purchase is paid is an internal control that protects:','["Competitors", "Customers'' opinions", "Corporate assets", "Advertising"]'::jsonb,2,'Approvals limit misuse.','original'),
('127.257.d.2.E',4,'Having different employees authorize payments, sign checks, and reconcile the bank statement is called:','["Double billing", "Tax planning", "Job rotation only", "Separation of duties"]'::jsonb,3,'Separation reduces fraud risk.','original'),
('127.257.d.2.F',3,'A work sheet for a corporation helps the accountant prepare:','["Financial statements", "Employee schedules", "Marketing plans", "Sales calls"]'::jsonb,0,'Work sheets feed statements.','original'),
('127.257.d.2.F',4,'Net income of $90,000 less dividends of $30,000 adds how much to retained earnings?','["$90,000", "$60,000", "$30,000", "$120,000"]'::jsonb,1,'90,000 - 30,000 = 60,000.','original'),
('127.257.d.2.G',3,'Consolidated financial statements combine the statements of:','["A company and its customers", "Two unrelated competitors", "A parent company and its subsidiaries", "A bank and its depositors"]'::jsonb,2,'Consolidation presents a single entity.','original'),
('127.257.d.2.G',4,'In consolidation, sales between the parent and its subsidiary are:','["Ignored forever", "Reported twice", "Doubled", "Eliminated"]'::jsonb,3,'Intercompany transactions are removed.','original'),
('127.257.d.2.H',3,'Corporate tax accounting is concerned with:','["Measuring and reporting income taxes the corporation owes", "Advertising", "Setting product prices", "Hiring accountants"]'::jsonb,0,'It handles the tax obligations.','original'),
('127.257.d.2.H',4,'Taxable income can differ from book income because of timing differences such as:','["The office address", "Depreciation methods", "The company logo", "Employee birthdays"]'::jsonb,1,'Tax and book depreciation differ.','original'),
('127.257.d.2.I',3,'A corporation has taxable income of $200,000 and a 21% tax rate. Its federal tax is:','["$4,200", "$21,000", "$42,000", "$200,000"]'::jsonb,2,'0.21 x 200,000 = 42,000.','original'),
('127.257.d.2.I',4,'To earn an after-tax profit of $79,000 at a 21% rate, the pre-tax target profit is:','["$121,000", "$79,000", "$21,000", "$100,000"]'::jsonb,3,'79,000 / 0.79 = 100,000.','original'),
('127.257.d.3.A',3,'A company''s annual report is mainly sent to:','["Shareholders and other stakeholders", "Customers'' neighbors", "School boards", "Competitors only"]'::jsonb,0,'Annual reports inform owners.','original'),
('127.257.d.3.A',4,'Besides financial statements, an annual report usually includes the:','["Trade secrets", "Management discussion and the auditor''s report", "Employee salaries by name", "Customer passwords"]'::jsonb,1,'MD&A and audit opinion are standard.','original'),
('127.257.d.3.B',3,'Financial ratios help decision makers by turning raw numbers into:','["Legal advice", "Marketing slogans", "Comparable measures of performance", "Random digits"]'::jsonb,2,'Ratios standardize comparison.','original'),
('127.257.d.3.B',4,'A lender sees a falling current ratio and rising debt. The lender will most likely:','["Forgive the loan", "Ignore the trend", "Offer a lower rate", "Tighten credit terms"]'::jsonb,3,'Weaker liquidity raises risk.','original'),
('127.257.d.3.C',3,'Current assets of $80,000 and current liabilities of $40,000 give a current ratio of:','["2.0", "1.5", "0.5", "4.0"]'::jsonb,0,'80,000 / 40,000 = 2.','original'),
('127.257.d.3.C',4,'With cash $10,000, receivables $30,000, inventory $40,000, and current liabilities $40,000, the quick ratio is:','["2.0", "1.0", "0.5", "0.25"]'::jsonb,1,'(10,000 + 30,000)/40,000 = 1.0.','original'),
('127.257.d.3.D',3,'Sales of $500,000 and cost of goods sold of $300,000 give a gross profit margin of:','["60%", "20%", "40%", "67%"]'::jsonb,2,'200,000/500,000 = 40%.','original'),
('127.257.d.3.D',4,'Net income of $30,000 on sales of $500,000 and total assets of $300,000 gives return on assets of:','["60%", "6%", "1%", "10%"]'::jsonb,3,'30,000/300,000 = 10%.','original'),
('127.257.d.3.E',3,'Cost of goods sold of $240,000 and average inventory of $40,000 give an inventory turnover of:','["6 times", "0.17 times", "200 times", "12 times"]'::jsonb,0,'240,000/40,000 = 6.','original'),
('127.257.d.3.E',4,'Credit sales of $600,000 and average receivables of $50,000 give an average collection period of about:','["12 days", "30 days", "365 days", "60 days"]'::jsonb,1,'Turnover 12; 365/12 is about 30.','original'),
('127.257.d.3.F',3,'An operating ratio compares operating expenses plus cost of goods sold to:','["Cash", "Owner''s equity", "Net sales", "Total assets"]'::jsonb,2,'Operating ratio = operating costs / net sales.','original'),
('127.257.d.3.F',4,'Operating costs of $450,000 on net sales of $500,000 give an operating ratio of:','["10%", "45%", "111%", "90%"]'::jsonb,3,'450,000/500,000 = 0.90.','original'),
('127.257.d.3.G',3,'Total liabilities of $200,000 and owners'' equity of $100,000 give a debt-to-equity ratio of:','["2.0", "3.0", "0.5", "1.0"]'::jsonb,0,'200,000/100,000 = 2.','original'),
('127.257.d.3.G',4,'Net operating income of $150,000 and annual debt payments of $100,000 give a debt service coverage ratio of:','["2.5", "1.5", "0.67", "1.0"]'::jsonb,1,'150,000/100,000 = 1.5.','original'),
('127.257.d.3.H',3,'Comparing a company''s ratios to industry averages shows how it performs relative to:','["Last century", "The weather", "Its competitors", "Its customers"]'::jsonb,2,'Benchmarks show relative standing.','original'),
('127.257.d.3.H',4,'A firm''s profit margin is 4% while its industry averages 9%. The comparison suggests the firm may need to:','["Close its bank account", "Issue more shares", "Do nothing", "Cut costs or raise prices"]'::jsonb,3,'Below-benchmark margin signals a problem.','original'),
('127.257.d.3.I',3,'A good recommendation based on ratios should be supported by:','["Specific numbers and comparisons", "Rumors", "Opinion alone", "Slogans"]'::jsonb,0,'Evidence-based recommendations are credible.','original'),
('127.257.d.3.I',4,'When presenting ratio findings, the accountant should first state:','["A list of employee names", "The conclusion and the key supporting ratios", "A joke", "An unrelated story"]'::jsonb,1,'Lead with findings.','original'),
('127.257.d.4.A',3,'A cost driver is a factor that:','["Hires staff", "Sets taxes", "Causes a cost to change", "Prints invoices"]'::jsonb,2,'Drivers explain cost behavior.','original'),
('127.257.d.4.A',4,'Machine hours are a likely cost driver for:','["Office decorations", "Rent for the year", "Sales commissions", "Maintenance and electricity in a factory"]'::jsonb,3,'More machine hours raise those costs.','original'),
('127.257.d.4.B',3,'A company has fixed costs of $60,000, a $20 selling price, and a $12 variable cost per unit. Its break-even point is:','["7,500 units", "5,000 units", "3,000 units", "12,000 units"]'::jsonb,0,'60,000 / 8 = 7,500.','original'),
('127.257.d.4.B',4,'To earn a $20,000 profit with those same figures, the company must sell:','["8,000 units", "10,000 units", "2,500 units", "7,500 units"]'::jsonb,1,'(60,000 + 20,000)/8 = 10,000.','original'),
('127.257.d.4.C',3,'A shop that builds custom furniture and tracks cost for each order uses:','["Break-even costing", "Pay-as-you-go costing", "Job order costing", "Process costing"]'::jsonb,2,'Custom work is costed by job.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_46_v1'
from (values
('127.257.d.4.C',4,'A refinery that mixes identical units continuously and averages cost per unit uses:','["Project costing only", "Standard sales costing", "Job order costing", "Process costing"]'::jsonb,3,'Continuous identical output uses process costing.','original'),
('127.257.d.4.D',3,'Beginning finished goods $20,000, cost of goods manufactured $150,000, and ending finished goods $30,000 give cost of goods sold of:','["$140,000", "$200,000", "$130,000", "$160,000"]'::jsonb,0,'20,000 + 150,000 - 30,000 = 140,000.','original'),
('127.257.d.4.D',4,'A manufacturer''s cost of goods manufactured includes direct materials, direct labor, and:','["Office rent", "Manufacturing overhead", "Interest on loans", "Selling expenses"]'::jsonb,1,'Overhead is a product cost.','original'),
('127.257.d.4.E',3,'Estimated overhead of $120,000 and 8,000 direct labor hours give a predetermined overhead rate of:','["$0.07 per hour", "$150 per hour", "$15 per hour", "$960 per hour"]'::jsonb,2,'120,000 / 8,000 = 15.','original'),
('127.257.d.4.E',4,'A plant estimates $300,000 overhead on 20,000 machine hours. The rate per machine hour is:','["$6,000", "$150", "$1.50", "$15"]'::jsonb,3,'300,000 / 20,000 = 15.','original'),
('127.257.d.4.F',3,'A job uses 40 direct labor hours at a $15 overhead rate. Overhead applied to the job is:','["$600", "$375", "$55", "$60"]'::jsonb,0,'40 x 15 = 600.','original'),
('127.257.d.4.F',4,'Job 12 used 25 machine hours at $18 per hour and $200 of materials. Overhead applied is:','["$18", "$450", "$650", "$225"]'::jsonb,1,'25 x 18 = 450.','original'),
('127.257.d.4.G',3,'Cost accounting information helps managers make decisions about:','["Employee birthdays", "Parking", "Pricing, production, and cost control", "Office colors"]'::jsonb,2,'Costs inform choices.','original'),
('127.257.d.4.G',4,'When deciding whether to drop a product line, a manager compares the revenue lost with the costs that are:','["Unchangeable", "Past", "Allocated arbitrarily", "Avoidable"]'::jsonb,3,'Only avoidable costs matter.','original'),
('127.257.d.4.H',3,'A flexible budget differs from a static budget because it:','["Adjusts to the actual level of activity", "Never changes", "Uses last year only", "Ignores sales"]'::jsonb,0,'Flexible budgets scale with volume.','original'),
('127.257.d.4.H',4,'Planned production of 10,000 units at $4 variable cost each gives a budget of $40,000. At 12,000 units the flexible budget is:','["$52,000", "$48,000", "$12,000", "$40,000"]'::jsonb,1,'12,000 x 4 = 48,000.','original'),
('127.257.d.4.I',3,'Budgeted materials cost is $10,000 and actual cost is $11,200. The variance is:','["$10,000 unfavorable", "$21,200 favorable", "$1,200 unfavorable", "$1,200 favorable"]'::jsonb,2,'Actual exceeds budget.','original'),
('127.257.d.4.I',4,'A variance analysis is most useful when managers:','["Ignore all variances", "Delete the budget", "Only reward favorable ones", "Investigate causes of large variances"]'::jsonb,3,'Analysis supports corrective action.','original'),
('127.257.d.4.J',3,'Allocating a share of the plant''s utility bill to each department is an example of:','["Cost allocation", "Tax planning", "Depreciation", "Cost avoidance"]'::jsonb,0,'Shared costs are spread across users.','original'),
('127.257.d.4.J',4,'A fair basis for allocating building rent to departments is usually:','["Random choice", "Square footage used", "Alphabetical order", "Number of employees'' pets"]'::jsonb,1,'Allocation base should reflect usage.','original'),
('127.257.d.4.K',3,'A product sells for $50 and has $30 in variable costs. Its contribution margin per unit is:','["$50", "$30", "$20", "$80"]'::jsonb,2,'50 - 30 = 20.','original'),
('127.257.d.4.K',4,'That product''s contribution margin ratio is:','["60%", "25%", "20%", "40%"]'::jsonb,3,'20 / 50 = 0.40.','original'),
('127.257.d.4.L',3,'In a make-or-buy decision, relevant costs are those that:','["Differ between the alternatives", "Already occurred", "Are the same in both", "Are fixed regardless"]'::jsonb,0,'Only differences matter.','original'),
('127.257.d.4.L',4,'Making a part costs $8 in variable cost plus $2 of avoidable fixed cost. Buying costs $11. The relevant cost of making is:','["$11 per unit", "$10 per unit", "$8 per unit", "$3 per unit"]'::jsonb,1,'8 + 2 = 10.','original'),
('127.257.d.4.M',3,'Making costs $10 per unit and buying costs $11. With no other factors, the company should:','["Raise prices", "Buy the part", "Make the part", "Cancel production"]'::jsonb,2,'Making saves $1 per unit.','original'),
('127.257.d.4.M',4,'A special order at $14 per unit has $10 variable cost and the plant has idle capacity. Accepting it changes profit by:','["Adding $10 per unit", "Losing $4 per unit", "Adding $14 per unit", "Adding $4 per unit"]'::jsonb,3,'14 - 10 = 4 contribution.','original'),
('127.257.d.4.N',3,'A written recommendation for a make-or-buy decision should state the decision and:','["The cost analysis supporting it", "Only the date", "Only the price", "An apology"]'::jsonb,0,'Support the choice with data.','original'),
('127.257.d.4.N',4,'A recommendation to reject a special order should mention any qualitative factors such as:','["Office plants", "Effects on regular customers'' prices", "The CEO''s birthday", "Lunch menus"]'::jsonb,1,'Qualitative factors can change the choice.','original'),
('127.257.d.4.O',3,'Allocating service department costs to producing departments is done in order to:','["Skip budgeting", "Hide expenses", "Show the full cost of products", "Raise taxes"]'::jsonb,2,'Allocation spreads indirect costs.','original'),
('127.257.d.4.O',4,'A maintenance department costs $60,000 and serves Dept A (3,000 hours) and Dept B (1,000 hours). Dept A is allocated:','["$30,000", "$60,000", "$15,000", "$45,000"]'::jsonb,3,'3/4 x 60,000 = 45,000.','original'),
('127.257.d.4.P',3,'A cost of production report in a process system summarizes costs and:','["Equivalent units of output", "Advertising slogans", "Competitor prices", "Employee names"]'::jsonb,0,'Reports track units and costs.','original'),
('127.257.d.4.P',4,'Process costing of $90,000 over 30,000 equivalent units gives a cost per equivalent unit of:','["$0.33", "$3", "$30", "$300"]'::jsonb,1,'90,000 / 30,000 = 3.','original'),
('127.257.d.5.A',3,'A central goal of corporate financial management is to:','["Minimize all spending", "Avoid investors", "Maximize shareholder wealth", "Maximize office size"]'::jsonb,2,'Value for owners guides decisions.','original'),
('127.257.d.5.A',4,'The three main decisions of corporate finance are investing, financing, and:','["Hiring decisions", "Naming decisions", "Marketing decisions", "Dividend decisions"]'::jsonb,3,'Dividends are the third pillar.','original'),
('127.257.d.5.B',3,'Efficient capital markets help companies by:','["Pricing securities fairly and connecting them to investors", "Running factories", "Setting wages", "Banning stock sales"]'::jsonb,0,'Efficient markets allocate funds.','original'),
('127.257.d.5.B',4,'In an efficient market, new public information about a company is reflected in its stock price:','["Only in December", "Quickly", "Never", "After many years"]'::jsonb,1,'Efficiency means fast adjustment.','original'),
('127.257.d.5.C',3,'Capital budgeting is the process of evaluating:','["Daily lunch orders", "Payroll dates", "Long-term investments such as new equipment", "Parking spaces"]'::jsonb,2,'Capital projects last years.','original'),
('127.257.d.5.C',4,'A capital budgeting project is generally accepted when its return exceeds the firm''s:','["Sales growth", "Tax rate", "Number of employees", "Cost of capital"]'::jsonb,3,'Return must beat financing cost.','original'),
('127.257.d.5.D.i',3,'A machine costs $100,000. Shipping is $5,000 and installation is $5,000. The initial investment is:','["$110,000", "$10,000", "$100,000", "$105,000"]'::jsonb,0,'100,000 + 5,000 + 5,000.','original'),
('127.257.d.5.D.i',4,'The firm sells the old machine for $12,000 and has no tax effect. The new machine costs $110,000 installed. Net initial investment is:','["$12,000", "$98,000", "$110,000", "$122,000"]'::jsonb,1,'110,000 - 12,000 = 98,000.','original'),
('127.257.d.5.D.ii',3,'A project adds $20,000 in net income and $15,000 in depreciation. Ignoring interest, operating cash inflow is:','["$5,000", "$20,000", "$35,000", "$15,000"]'::jsonb,2,'20,000 + 15,000.','original'),
('127.257.d.5.D.ii',4,'Depreciation is added back when finding cash flow because it is:','["A tax refund", "A cash expense", "Revenue", "A noncash expense"]'::jsonb,3,'No cash leaves the firm.','original'),
('127.257.d.5.D.iii',3,'At the end of a project the firm sells the equipment for $10,000 and recovers $5,000 of working capital. Terminal cash flow is:','["$15,000", "$10,000", "$5,000", "$50,000"]'::jsonb,0,'10,000 + 5,000.','original'),
('127.257.d.5.D.iii',4,'Terminal cash flow is the cash flow that occurs:','["Before approval", "In the final year of a project from its end", "Every month", "At the start"]'::jsonb,1,'It arises at project termination.','original'),
('127.257.d.5.E.i',3,'In capital budgeting, relevant cash flows are those that:','["Occurred last year", "Are the same with or without it", "Change because of the project", "Never change"]'::jsonb,2,'Only incremental flows count.','original'),
('127.257.d.5.E.i',4,'A sunk cost, such as money already spent on a study, is:','["Doubled", "Added to the cost", "Counted twice", "Ignored in the decision"]'::jsonb,3,'Sunk costs are not relevant.','original'),
('127.257.d.5.E.ii',3,'The payback period measures the time needed to:','["Recover the initial investment from cash inflows", "Earn the highest return", "Pay all taxes", "Repay all shareholders"]'::jsonb,0,'Payback is recovery time.','original'),
('127.257.d.5.E.ii',4,'A weakness of the payback period is that it ignores:','["The project''s name", "Cash flows after the payback date and the time value of money", "The first year", "The initial cost"]'::jsonb,1,'Simple payback has limits.','original'),
('127.257.d.5.E.iii',3,'A $100,000 project returns $25,000 each year. The payback period is:','["25 years", "5 years", "4 years", "2.5 years"]'::jsonb,2,'100,000 / 25,000 = 4.','original'),
('127.257.d.5.E.iii',4,'A $60,000 project returns $10,000, $20,000, and then $30,000 in years 1 to 3. Payback occurs at the end of year:','["4", "1", "2", "3"]'::jsonb,3,'Cumulative cash reaches 60,000 at year 3.','original'),
('127.257.d.5.E.iv',3,'If a project''s internal rate of return exceeds the required return, its net present value is generally:','["Positive", "Negative", "Undefined", "Zero"]'::jsonb,0,'IRR above hurdle means positive NPV.','original'),
('127.257.d.5.E.iv',4,'The internal rate of return is the discount rate at which NPV equals:','["The initial cost", "Zero", "One", "The tax rate"]'::jsonb,1,'IRR sets NPV to zero.','original'),
('127.257.d.5.E.v',3,'A project costs $9,000 and returns $12,100 in 2 years. At 10%, the present value of the inflow is $10,000, so NPV is:','["-$1,000", "$3,100", "$1,000", "$12,100"]'::jsonb,2,'10,000 - 9,000 = 1,000.','original'),
('127.257.d.5.E.v',4,'The future value of $5,000 invested for 2 years at 6% compounded annually is about:','["$5,300", "$5,600", "$6,000", "$5,618"]'::jsonb,3,'5,000 x 1.1236 = 5,618.','original'),
('127.257.d.5.E.vi',3,'A $1,000 investment returns $1,210 after 2 years. The internal rate of return is:','["10%", "12.1%", "5%", "21%"]'::jsonb,0,'1,000 x 1.1^2 = 1,210.','original'),
('127.257.d.5.E.vi',4,'Since IRR is found where NPV is zero, analysts often compute it using:','["A dictionary", "Trial and error or a financial calculator", "A thermometer", "A ruler"]'::jsonb,1,'Iteration finds the rate.','original'),
('127.257.d.5.F',3,'The financial planning process begins with:','["Selling stock", "Closing the books", "Setting goals and forecasting", "Paying dividends"]'::jsonb,2,'Plans start with goals and forecasts.','original'),
('127.257.d.5.F',4,'Compared with short-term operating plans, long-term strategic plans usually cover:','["One week", "One day", "One hour", "Several years"]'::jsonb,3,'Strategic plans look far ahead.','original'),
('127.257.d.5.G.i',3,'A cash budget shows expected cash:','["Receipts and disbursements for a period", "Product colors", "Employee birthdays", "Advertising slogans"]'::jsonb,0,'It tracks inflows and outflows.','original'),
('127.257.d.5.G.i',4,'Managers use cash budgets primarily to avoid:','["Paying taxes", "Unexpected cash shortages", "Hiring", "Selling products"]'::jsonb,1,'Budgets reveal needs in advance.','original')
